mapper.select:


    deleted = 0
     and child_id = #{childId}
     and start_date = #{startDate}
     and end_date = #{endDate}
     and days = #{days}
     and reason like concat('%', #{reason}, '%')
     and status = #{status}
     and approver like concat('%', #{approver}, '%')
     and approve_time = #{approveTime}

order by id desc
